<template>
<Teleport to="body"><div class="zero-modal" role="dialog" aria-modal="true" aria-label="Zero Block" @keydown.esc="$emit('close')">
<header><div><strong>Zero Block</strong><span>Свободная композиция</span></div><div class="zero-tools"><button type="button" @click="$emit('close')">Отмена</button><button type="button" class="primary" @click="$emit('apply', draft)">Применить</button></div></header>
<div class="zero-workspace">
<aside><small>ДОБАВИТЬ СЛОЙ</small><div class="zero-tools"><button v-for="(name,kind) in kinds" :key="kind" type="button" @click="add(kind)">{{ name }}</button></div><small>СЛОИ</small><button v-for="(layer,index) in draft.layers" :key="layer.id" type="button" class="zero-layer" :class="{on: selected === layer.id}" @click="selected=layer.id"><span>{{ kinds[layer.kind] }}</span><span>{{ index+1 }}</span></button><p>Перетаскивайте слои на холсте. Порядок в списке определяет наложение.</p></aside>
<main><div class="zero-stage" ref="stage" :style="{aspectRatio:`600 / ${draft.height}`, background:draft.bg}" @pointermove="drag" @pointerup="stop" @pointercancel="stop">
<div v-for="layer in draft.layers" :key="layer.id" class="zero-object" :class="{selected: selected === layer.id}" :style="layerStyle(layer)" @pointerdown.prevent="start($event,layer)">
<div v-if="layer.kind==='rect'" :style="{width:'100%',height:'100%',background:layer.color,borderRadius:layer.radius+'px'}"></div>
<div v-else-if="layer.kind==='text'" :style="{fontSize:`${layer.size/6}cqw`,color:layer.color,fontWeight:layer.weight,lineHeight:1.2,whiteSpace:'pre-wrap'}">{{ layer.text }}</div>
<img v-else :src="safeUrl(layer.src)" alt="" draggable="false" style="width:100%;height:100%;object-fit:cover">
</div></div><p>600 × {{ draft.height }} · Масштабируется под ширину страницы</p></main>
<aside><template v-if="active"><small>{{ kinds[active.kind] }}</small><label v-if="active.kind==='text'">Текст<textarea v-model="active.text" rows="4" /></label><label v-if="active.kind==='image'">Ссылка на изображение<input v-model="active.src" placeholder="https://…"></label><div class="zero-grid"><label v-for="(name,key) in measures" :key="key">{{ name }}<input v-model.number="active[key]" type="number" :aria-label="name"></label></div><label v-if="active.kind!=='image'">Цвет<input v-model="active.color" type="color"></label><label v-if="active.kind==='text'">Размер текста<input v-model.number="active.size" type="number" min="8" max="160"></label><label v-if="active.kind==='rect'">Скругление<input v-model.number="active.radius" type="number" min="0" max="300"></label><div class="zero-tools"><button type="button" @click="raise">На передний план</button><button type="button" @click="remove">Удалить слой</button></div></template><small>ХОЛСТ</small><label>Высота<input v-model.number="draft.height" type="number" min="120" max="1200"></label><label>Фон<input v-model="draft.bg" type="color"></label></aside>
</div></div></Teleport>
</template>
<script setup>
import {computed,ref} from 'vue';
import {safeUrl} from '@/Support/descriptionBlocks';
const props=defineProps({value:{type:Object,required:true}});defineEmits(['apply','close']);
const draft=ref(JSON.parse(JSON.stringify(props.value)));const selected=ref(draft.value.layers[0]?.id);const stage=ref(null);const active=computed(()=>draft.value.layers.find(l=>l.id===selected.value));
const kinds={text:'Текст',rect:'Фигура',image:'Фото'};const measures={x:'X',y:'Y',w:'Ширина',h:'Высота',rot:'Поворот'};let moving=null;
function add(kind){const layer={id:crypto.randomUUID(),kind,x:40,y:40,w:kind==='text'?420:160,h:100,rot:0,color:kind==='text'?'#202637':'#f27b63',text:'Ваш заголовок',size:36,weight:700,radius:16,src:''};draft.value.layers.push(layer);selected.value=layer.id;}
function layerStyle(l){return {left:l.x/6+'%',top:l.y/draft.value.height*100+'%',width:l.w/6+'%',height:l.h/draft.value.height*100+'%',transform:`rotate(${l.rot||0}deg)`};}
function start(event,layer){selected.value=layer.id;moving={layer,x:event.clientX,y:event.clientY,lx:layer.x,ly:layer.y};event.currentTarget.setPointerCapture(event.pointerId);}
function drag(event){if(!moving)return;const scale=600/stage.value.getBoundingClientRect().width;moving.layer.x=Math.round(moving.lx+(event.clientX-moving.x)*scale);moving.layer.y=Math.round(moving.ly+(event.clientY-moving.y)*scale);}
function stop(){moving=null;}
function raise(){if(!active.value)return;const l=active.value;draft.value.layers=draft.value.layers.filter(x=>x.id!==l.id);draft.value.layers.push(l);}
function remove(){draft.value.layers=draft.value.layers.filter(x=>x.id!==selected.value);selected.value=draft.value.layers[0]?.id;}
</script>
<style scoped>
.zero-modal{position:fixed;inset:12px;z-index:100;background:#fff;color:#252b39;border-radius:16px;box-shadow:0 0 0 100vmax #171d2b99;overflow:auto;font-family:system-ui;display:flex;flex-direction:column}.zero-modal header{display:flex;justify-content:space-between;align-items:center;padding:20px 24px;border-bottom:1px solid #e4e6ec}.zero-modal header span{display:block;font-size:12px;color:#8a909e;margin-top:4px}.zero-tools{display:flex;flex-wrap:wrap;gap:6px;margin:12px 0}.zero-modal button{border:1px solid #e0e4ed;border-radius:8px;padding:9px 12px;background:white;color:inherit;font-size:12px;cursor:pointer}.zero-modal button:hover{background:#eef1ff}.zero-modal button.primary{background:#4c68eb;color:white;border-color:#4c68eb}.zero-workspace{display:grid;grid-template-columns:220px minmax(0,1fr) 260px;flex:1}.zero-workspace aside{padding:24px 18px}.zero-workspace aside:last-child{background:#fafbfe}.zero-modal small{display:block;margin:12px 0 18px;font-size:10px;letter-spacing:.1em;color:#9298a5}.zero-layer{display:flex;justify-content:space-between;width:100%;margin:6px 0}.zero-layer.on{border-color:#4c68eb;background:#eef1ff}.zero-workspace main{background:#eef0f5;padding:64px 32px}.zero-stage{position:relative;container-type:inline-size;width:100%;max-width:760px;margin:auto;overflow:hidden;box-shadow:0 12px 40px -20px #1c1f2770;touch-action:none}.zero-object{position:absolute;cursor:move;touch-action:none}.zero-object.selected{outline:2px solid #4c68eb}.zero-modal label{display:grid;gap:6px;font-size:11px;color:#737b8e;margin-bottom:16px}.zero-modal input,.zero-modal textarea{width:100%;border:1px solid #e0e4ed;border-radius:7px;padding:8px;font-size:13px;background:white;color:#252b39}.zero-modal input[type=color]{height:36px}.zero-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.zero-modal p{font-size:11px;color:#8a909e;line-height:1.7}.zero-workspace main>p{text-align:center;margin-top:20px}@media(max-width:850px){.zero-workspace{grid-template-columns:150px minmax(0,1fr)}.zero-workspace aside:last-child{grid-column:1/-1}.zero-workspace main{padding:32px 16px}}@media(max-width:500px){.zero-modal{inset:4px}.zero-workspace{display:flex;flex-direction:column}.zero-workspace aside{padding:12px}.zero-layer{display:inline-flex;width:auto;margin-right:6px}.zero-workspace main{padding:20px 12px}}
</style>
